export function sameLocation(a,b){return Math.abs(a.lat-b.lat)<.0001&&Math.abs(a.lon-b.lon)<.0001}
export function requestURL(field){return `https://power.larc.nasa.gov/api/temporal/daily/point?parameters=T2M,T2M_MAX,PRECTOTCORR&community=AG&longitude=${field.lon}&latitude=${field.lat}&start=20210601&end=20250531&format=JSON`}
export function createDataClient(fetcher=fetch){const cache=new Map();let generation=0,controller;return {cancel(){generation++;controller?.abort()},async load(field){const current=++generation;controller?.abort();const requestController=new AbortController();controller=requestController;const key=`${field.lat},${field.lon}`;if(cache.has(key))return {record:cache.get(key),current:()=>current===generation};const saved=sameLocation(field,{lat:18.52,lon:73.86}),url=saved?'./data/pune-history.json':requestURL(field);const timer=setTimeout(()=>requestController.abort(),60000);try{const response=await fetcher(url,{signal:requestController.signal});if(!response.ok)throw Error(`NASA data request failed (${response.status}).`);const data=await response.json(),record=saved?data:{request_url:url,retrieved_at:new Date().toISOString(),requested_location:{lat:field.lat,lon:field.lon},product:'NASA POWER Daily',data};if(!record.data?.properties?.parameter)throw Error('Weather record is invalid.');cache.set(key,record);return {record,current:()=>current===generation}}finally{clearTimeout(timer)}}}}
